root=pathlib.Path("/workspace/results/eval_outputs")
for step in [0,50,100,150,200,250,300,350,400]:
 print("\nSTEP",step)
 prev=None
 for split in ["val","ood_val"]:
  rs=[json.loads(x) for x in (root/f"step{step}_{split}.jsonl").read_text().splitlines()]
  qs=collections.Counter(r["question"] for r in rs)
  exact=[r for r in rs if r["correct"]]; wrong=[r for r in rs if not r["correct"]]
  print(split,"unique_q",len(qs),"q types",qs.most_common(8))
  print(" gold",collections.Counter(r["gold"] for r in rs).most_common(12),"pred",collections.Counter(r["pred"] for r in rs).most_common(12))
  if step in [100,400]:
   for r in wrong[:3]: print("WRONG",json.dumps(r,ensure_ascii=False)[:1800])
   if exact: print("RIGHT",json.dumps(exact[0],ensure_ascii=False)[:1300])
'

